import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Validates report type against known types
    private boolean isValidReportType(String type) {
        String[] valid = {"sales", "inventory", "returns", "shipping"};
        for (String v : valid) {
            if (v.equals(type)) return true;
        }
        return false;
    }

    // Strips potentially dangerous HTML for XSS prevention
    private String sanitizeForDisplay(String input) {
        if (input == null) return "";
        return input.replace("<", "&lt;").replace(">", "&gt;")
                    .replace("\"", "&quot;").replace("'", "&#39;");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String region = req.getParameter("region");

        if (reportType == null || !isValidReportType(reportType)) {
            resp.setStatus(400);
            out.print("{\"error\": \"Invalid report type\"}");
            return;
        }

        // Date validation - must be YYYY-MM-DD format
        if (dateFrom != null && !dateFrom.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.setStatus(400);
            out.print("{\"error\": \"Invalid date format\"}");
            return;
        }
        if (dateTo != null && !dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.setStatus(400);
            out.print("{\"error\": \"Invalid date format\"}");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query - region filter is user-controlled
            String baseQuery = "SELECT id, amount, created_at, region, description FROM " +
                              reportType + "_reports WHERE created_at BETWEEN ? AND ?";

            if (region != null && !region.isEmpty()) {
                // Region comes from a dropdown populated by /api/regions endpoint
                baseQuery += " AND region = '" + region + "'";
            }

            baseQuery += " ORDER BY created_at DESC LIMIT 500";

            logger.info("Executing report query for type=" + reportType);

            PreparedStatement stmt = conn.prepareStatement(baseQuery);
            stmt.setString(1, dateFrom != null ? dateFrom : "2020-01-01");
            stmt.setString(2, dateTo != null ? dateTo : "2099-12-31");

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("amount", rs.getDouble("amount"));
                row.put("created_at", rs.getString("created_at"));
                row.put("region", sanitizeForDisplay(rs.getString("region")));
                row.put("description", sanitizeForDisplay(rs.getString("description")));
                results.put(row);
            }

            JSONObject response = new JSONObject();
            response.put("report_type", reportType);
            response.put("count", results.length());
            response.put("data", results);
            out.print(response.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.setStatus(500);
            out.print("{\"error\": \"Internal server error\"}");
        }
    }
}
